using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CompanionRarity", menuName = "Data/Battle/Companions/CompanionRarity")]
public class CompanionRarity : ScriptableObject
{
	[SerializeField]
	private CompanionRarityTier[] companionRarityTiers;

	public CompanionRarityTier GetCompanionRarityTier()
	{
		int num = Random.Range(1, 101);
		float num2 = 0f;
		for (int i = 0; i < companionRarityTiers.Length; i++)
		{
			num2 += (float)companionRarityTiers[i].AppearancePercentage;
			if ((float)num <= num2)
			{
				return companionRarityTiers[i];
			}
		}
		return null;
	}
}
